@section('content')<div class="page-header"><div><p class="eyebrow">AKUN & PENGATURAN</p><h1>Rute Pengangkutan</h1><p>Tinjau dan selesaikan titik pengangkutan sesuai urutan.</p></div><a class="button" href="{{ route('petugas.rute.skema') }}"><i data-lucide="map"></i>Lihat Skema Rute</a></div>@if(!$rute)<div class="card"><x-empty-state title="Belum ada rute yang ditugaskan hari ini."/></div>@else @php($points=$run?->titik ?? $rute->titik) @php($done=$run?->titik->where('status','selesai')->count()??0) @php($total=$points->count()) @php($percent=$total ? round($done/$total*100):0)<div class="banner"><div class="page-header"><div><small>PROGRES RUTE</small><h2>{{ $done }} dari {{ $total }} lokasi ({{ $percent }}%)</h2><p>{{ $total-$done }} tersisa &bull; {{ $rute->kode }}</p></div><div><small>Waktu berjalan</small><strong @if($run && $run->status!=='selesai') data-started="{{ $run->mulai_at->toIso8601String() }}" @endif>{{ $run ? $run->mulai_at->diff($run->selesai_at??now())->format('%Hj %Im') : '00j 00m' }}</strong></div></div><div class="progress"><span style="width:{{ $percent }}%"></span></div></div>@if(!$run)<div class="notice">Rute belum dimulai. Tekan Mulai Rute untuk memulai tugas.</div><form method="post" action="{{ route('petugas.rute.mulai') }}">@csrf<button class="button" style="margin-bottom:20px">Mulai Rute</button></form>@endif @foreach($points as $point)<div class="card route-point {{ ($point->status??'')==='proses' ? 'current':'' }}"><span class="icon-box"><i data-lucide="{{ ($point->status??'')==='selesai' ? 'check-circle':'map-pin' }}"></i></span><div><h3>{{ $point->nama }}</h3><p>{{ $point->keterangan }} &bull; {{ str_replace(':','.',substr($point->jam_rencana,0,5)) }} WIB</p>@if($point->catatan)<small>Catatan: {{ $point->catatan }}</small>@endif @if(($point->status??'')==='proses')<form method="post" action="{{ route('petugas.rute.titik',$point) }}">@csrf @method('PATCH')<x-field name="catatan" label="Tambah Catatan" type="textarea" :value="$point->catatan"/><div class="actions"><button class="outline" name="selesai" value="0">Simpan Catatan</button><button class="button" name="selesai" value="1">Tandai Selesai</button></div></form>@endif</div><div><x-badge :status="$point->status??'menunggu'"/><a class="outline small" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination={{ $point->lat }},{{ $point->lng }}">Navigasi</a></div></div>@endforeach @endif @push('scripts')<script src="{{ asset('assets/js/petugas/rute.js') }}"></script>@endpush
